\begin{example}
\label{ex:figure-eight-curve}
\dcref{ch4:4.23}
The curve
\[
\gamma\colon(-\pi,\pi)\to\mathbb R^2,
\qquad \gamma(t)=(\sin 2t,\sin t),
\]
is an injective smooth immersion, but its velocity field is not extendible.
\end{example}

